1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Set;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.model.OwnerRegion;
10	
11	/**
12	 * Single source of truth for an owner's {@code memberId} and everything read back out of it.
13	 *
14	 * <p>The id unifies what used to be the separate {@code customerCode} and {@code membershipNumber}
15	 * (and the standalone {@code checkDigit}) into one value whose four segments run together with no
16	 * separators, formatted {@code <REGION><FY><HASH8><CHK>}:
17	 * <ul>
18	 * <li>{@code REGION} is the owner's region code, derived from the postcode (see
19	 * {@link OwnerRegion#localityOf}, which prefers the postcode and falls back to the city table), e.g.
20	 * {@code NSW}.</li>
21	 * <li>{@code FY} is the two-digit fiscal year — the last two digits of the owner's fiscal year, the
22	 * financial year (starting 1 July) of the business-day-adjusted registration date named by its
23	 * ending calendar year (see {@link OwnerFiscalYear}), e.g. {@code 27} for an October 2026
24	 * registration.</li>
25	 * <li>{@code HASH8} is the first eight upper-case hex characters of the SHA-256 of
26	 * {@code normalizedTelephone + lastName}, where {@code normalizedTelephone} is the E.164 telephone
27	 * (see {@link OwnerTelephone#toE164}) — the same region-and-hash identity used before.</li>
28	 * <li>{@code CHK} is a single Luhn check digit computed over the digits contained in
29	 * {@code <REGION><FY><HASH8>} (the letters of the region and hash are skipped).</li>
30	 * </ul>
31	 *
32	 * <p>There are no sequence numbers: the id depends only on the owner's own region, fiscal year,
33	 * telephone and last name, so it can be computed without coordinating through the database. The one
34	 * exception to the separator-free shape is collision handling: should two owners produce the same id,
35	 * {@link #deduplicate} appends a {@code -<n>} suffix to keep them distinct (see that method). Every
36	 * other identity value is derived from this id — the read-time {@code locality} and {@code fiscalYear}
37	 * and the create audit record all read the member id assigned here.
38	 */
39	public final class OwnerMemberId {
40	
41	    private OwnerMemberId() {
42	    }
43	
44	    /** The {@code <REGION><FY><HASH8><CHK>} member id for {@code owner}. */
45	    public static String memberId(Owner owner) {
46	        String region = OwnerRegion.localityOf(owner.getCity(), owner.getPostcode());
47	        String fy = OwnerFiscalYear.yy(owner.getRegistrationDate());
48	        String base = region + fy + hash8(owner.getTelephone(), owner.getLastName());
49	        return base + luhn(base);
50	    }
51	
52	    /**
53	     * The {@code HASH8} segment: the first eight upper-case hex characters of the SHA-256 of the
54	     * normalized (E.164) telephone concatenated with the last name.
55	     */
56	    static String hash8(String telephone, String lastName) {
57	        String normalizedTelephone = OwnerTelephone.toE164(telephone);
58	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
59	                + (lastName == null ? "" : lastName);
60	        try {
61	            byte[] digest = MessageDigest.getInstance("SHA-256")
62	                    .digest(key.getBytes(StandardCharsets.UTF_8));
63	            StringBuilder sb = new StringBuilder(8);
64	            for (int i = 0; i < 4; i++) {
65	                sb.append(String.format("%02X", digest[i]));
66	            }
67	            return sb.toString();
68	        }
69	        catch (NoSuchAlgorithmException ex) {
70	            throw new IllegalStateException("SHA-256 not available", ex);
71	        }
72	    }
73	
74	    /**
75	     * The single Luhn check digit (0-9) over the digits contained in {@code s}. Non-digit characters
76	     * (the region and hash letters) are skipped; the standard Luhn algorithm doubles every second
77	     * digit from the right, subtracting 9 when a doubled value exceeds 9, and the check digit is the
78	     * amount needed to round the running sum up to the next multiple of ten.
79	     */
80	    static int luhn(String s) {
81	        int sum = 0;
82	        boolean dbl = true;
83	        for (int i = s.length() - 1; i >= 0; i--) {
84	            char c = s.charAt(i);
85	            if (c < '0' || c > '9') {
86	                continue;
87	            }
88	            int d = c - '0';
89	            if (dbl) {
90	                d *= 2;
91	                if (d > 9) {
92	                    d -= 9;
93	                }
94	            }
95	            sum += d;
96	            dbl = !dbl;
97	        }
98	        return (10 - (sum % 10)) % 10;
99	    }
100	
101	    /**
102	     * De-duplicates {@code base} against the {@code existing} member ids: returns {@code base}
103	     * unchanged when it is not already taken, otherwise appends {@code -<n>} with the smallest
104	     * {@code n} of 2 or more that makes the id unique.
